             dict(landmarkId="baptistery", title="My beautiful San Giovanni", text="Here he was baptised, like every Florentine; he once broke one of the marble fonts to save a boy who was drowning in it, he says in the Inferno. Mosaics of the Last Judgement shine in the dome."),
             dict(spotId="speziale", title="A guildsman", text="To hold office a noble must belong to a guild. Dante joined the physicians and apothecaries about 1295; among the speziali's jars of pepper and pigment he is enrolled as 'Dante d'Aldighieri, poet'."),
             dict(landmarkId="duomo", title="The new cathedral rising", text="Arnolfo's masons are building the new front around old Santa Reparata. The city means its cathedral to be the largest in the world; no one yet knows how its crossing will be roofed."),
