             dict(landmarkId="baptistery", title="Copying the doors", text="On feast days the master sends you to draw from Ghiberti's gilded doors of the Baptistery, the school of every Florentine artist: perspective, figures, landscape, all in bronze."),
             dict(landmarkId="duomo", title="The ball on the lantern", when="27 May 1471", text="The shop has made the great copper ball for the top of Brunelleschi's lantern, gilded and soldered with burning-mirrors. Today it is hauled up with Brunelleschi's own hoists while the city watches and the bells ring."),
